package com.google.dotprompt.models;

import static com.google.common.truth.Truth.assertThat;

import com.fasterxml.jackson.annotation.JsonInclude.Include;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

@RunWith(JUnit4.class)
public class JsonSerializationTest {

  private final ObjectMapper mapper =
      new ObjectMapper().setSerializationInclusion(Include.NON_NULL);

  @Test
  public void testMediaPartSerialization() throws Exception {
    MediaPart part = new MediaPart(new MediaContent("http://example.com/image.png", "image/png"));
    String json = mapper.writeValueAsString(part);
    Map<String, Object> map = mapper.readValue(json, Map.class);

    // Structure: { "media": { "url": "...", "contentType": "..." } }
    assertThat(map).containsKey("media");
    Map<String, Object> media = (Map<String, Object>) map.get("media");
    assertThat(media).containsEntry("url", "http://example.com/image.png");
    assertThat(media).containsEntry("contentType", "image/png");
  }

  @Test
  public void testToolRequestPartSerialization() throws Exception {
    ToolRequestPart part =
        new ToolRequestPart(new ToolRequestContent("myTool", Map.of("arg", "val"), "ref-123"));
    String json = mapper.writeValueAsString(part);
    Map<String, Object> map = mapper.readValue(json, Map.class);

    // Structure: { "toolRequest": { "name": "...", "input": {...}, "ref": "..." } }
    assertThat(map).containsKey("toolRequest");
    Map<String, Object> req = (Map<String, Object>) map.get("toolRequest");
    assertThat(req).containsEntry("name", "myTool");
    assertThat(req).containsEntry("ref", "ref-123");
    assertThat((Map) req.get("input")).containsEntry("arg", "val");
  }

  @Test
  public void testToolResponsePartSerialization() throws Exception {
    ToolResponsePart part =
        new ToolResponsePart(new ToolResponseContent("myTool", Map.of("result", "ok"), "ref-123"));
    String json = mapper.writeValueAsString(part);
    Map<String, Object> map = mapper.readValue(json, Map.class);

    assertThat(map).containsKey("toolResponse");
    Map<String, Object> resp = (Map<String, Object>) map.get("toolResponse");
    assertThat(resp).containsEntry("name", "myTool");
    assertThat(resp).containsEntry("ref", "ref-123");
    assertThat((Map) resp.get("output")).containsEntry("result", "ok");
  }

  @Test
  public void testTextPartSerialization() throws Exception {
    TextPart part = new TextPart("hello");
    String json = mapper.writeValueAsString(part);
    Map<String, Object> map = mapper.readValue(json, Map.class);

    assertThat(map).containsEntry("text", "hello");
  }

  @Test
  public void testDataPartSerialization() throws Exception {
    DataPart part = new DataPart(Map.of("key", "value"));
    String json = mapper.writeValueAsString(part);
    Map<String, Object> map = mapper.readValue(json, Map.class);

    assertThat(map).containsKey("data");
    assertThat((Map) map.get("data")).containsEntry("key", "value");
  }

  @Test
  public void testPendingPartSerialization() throws Exception {
    PendingPart part = new PendingPart();
    String json = mapper.writeValueAsString(part);
    Map<String, Object> map = mapper.readValue(json, Map.class);

    assertThat(map).containsKey("metadata");
    assertThat((Map) map.get("metadata")).containsEntry("pending", true);
  }

  @Test
  public void testToolDefinitionSerialization() throws Exception {
    ToolDefinition tool =
        new ToolDefinition(
            "myTool", "A test tool", Map.of("type", "object"), Map.of("type", "string"));
    String json = mapper.writeValueAsString(tool);
    Map<String, Object> map = mapper.readValue(json, Map.class);

    assertThat(map).containsEntry("name", "myTool");
    assertThat(map).containsEntry("description", "A test tool");
    assertThat(map).containsKey("inputSchema");
    assertThat(map).containsKey("outputSchema");
  }

  @Test
  public void testPartDeserialization() throws Exception {
    String json = "{\"text\": \"hello\"}";
    Part part = mapper.readValue(json, Part.class);
    assertThat(part).isInstanceOf(TextPart.class);
    assertThat(((TextPart) part).text()).isEqualTo("hello");

    json = "{\"media\": {\"url\": \"http://example.com\", \"contentType\": \"image/png\"}}";
    part = mapper.readValue(json, Part.class);
    assertThat(part).isInstanceOf(MediaPart.class);
    assertThat(((MediaPart) part).media().url()).isEqualTo("http://example.com");

    json = "{\"toolRequest\": {\"name\": \"t\", \"input\": {}}}";
    part = mapper.readValue(json, Part.class);
    assertThat(part).isInstanceOf(ToolRequestPart.class);
    assertThat(((ToolRequestPart) part).toolRequest().name()).isEqualTo("t");
  }

  @Test
  public void testMessageSerialization() throws Exception {
    Message msg = new Message(Role.USER, List.of(new TextPart("hi")), Map.of("key", "val"));
    String json = mapper.writeValueAsString(msg);
    Map<String, Object> map = mapper.readValue(json, Map.class);

    assertThat(map).containsEntry("role", "user");
    assertThat(map).containsKey("content");
    assertThat(map).containsKey("metadata");
    assertThat((Map) map.get("metadata")).containsEntry("key", "val");
  }
}

# Java API

The `com.google.dotprompt` package is the Java implementation of the Dotprompt
file format.

## Installation

\=== "Maven"
`xml     <dependency>       <groupId>com.google.dotprompt</groupId>       <artifactId>dotprompt</artifactId>       <version>0.1.0</version>     </dependency>
    `

\=== "Gradle (Kotlin)"
`kotlin
    implementation("com.google.dotprompt:dotprompt:0.1.0")
    `

\=== "Gradle (Groovy)"
`groovy
    implementation 'com.google.dotprompt:dotprompt:0.1.0'
    `

## Quick Start

```java
import com.google.dotprompt.Dotprompt;
import com.google.dotprompt.DotpromptOptions;
import com.google.dotprompt.models.DataArgument;
import com.google.dotprompt.models.RenderedPrompt;

import java.util.Map;

public class Example {
    public static void main(String[] args) {
        String source = """
            ---
            model: gemini-pro
            input:
              schema:
                name: string
            ---
            Hello, {{name}}!
            """;

        Dotprompt dotprompt = new Dotprompt();

        DataArgument data = DataArgument.builder()
            .input(Map.of("name", "World"))
            .build();

        RenderedPrompt rendered = dotprompt.render(source, data, null);

        rendered.getMessages().forEach(message -> {
            System.out.printf("%s: %s%n", message.getRole(), message.getContent());
        });
    }
}
```

## Core Classes

### Dotprompt

The main entry point for working with Dotprompt templates.

```java
public class Dotprompt {
    // Constructors
    public Dotprompt();
    public Dotprompt(DotpromptOptions options);

    // Parsing
    public ParsedPrompt parse(String source);

    // Compilation
    public PromptFunction compile(String source);
    public PromptFunction compile(String source, PromptMetadata additionalMetadata);

    // Rendering
    public RenderedPrompt render(String source, DataArgument data);
    public RenderedPrompt render(String source, DataArgument data, PromptMetadata options);

    // Registration
    public Dotprompt defineHelper(String name, HelperFn fn);
    public Dotprompt definePartial(String name, String source);
    public Dotprompt defineTool(ToolDefinition definition);
}
```

### DotpromptOptions

Builder for configuring a Dotprompt instance.

```java
DotpromptOptions options = DotpromptOptions.builder()
    .defaultModel("gemini-pro")
    .modelConfigs(Map.of(
        "gemini-pro", Map.of("temperature", 0.7)
    ))
    .helpers(Map.of(
        "uppercase", (params, options) -> params.get(0).toString().toUpperCase()
    ))
    .partials(Map.of(
        "header", "Welcome to {{appName}}!"
    ))
    .build();

Dotprompt dotprompt = new Dotprompt(options);
```

## Models

### ParsedPrompt

Result of parsing a Dotprompt template.

```java
public class ParsedPrompt {
    public String getTemplate();
    public String getName();
    public String getDescription();
    public String getVariant();
    public String getVersion();
    public String getModel();
    public Object getConfig();
    public PromptInputConfig getInput();
    public PromptOutputConfig getOutput();
    public List<String> getTools();
    public List<ToolDefinition> getToolDefs();
    public Map<String, Map<String, Object>> getExt();
    public Map<String, Object> getRaw();
}
```

### RenderedPrompt

Result of rendering a Dotprompt template.

```java
public class RenderedPrompt extends PromptMetadata {
    public List<Message> getMessages();
}
```

### Message

A single message in a conversation.

```java
public class Message {
    public Role getRole();
    public List<Part> getContent();
    public Map<String, Object> getMetadata();
}

public enum Role {
    USER("user"),
    MODEL("model"),
    TOOL("tool"),
    SYSTEM("system");
}
```

### Part

Content within a message. Part is a sealed interface with several implementations:

```java
public sealed interface Part permits TextPart, MediaPart, DataPart,
    ToolRequestPart, ToolResponsePart, PendingPart {
}

public record TextPart(String text, Map<String, Object> metadata) implements Part {}

public record MediaPart(MediaContent media, Map<String, Object> metadata) implements Part {}

public record MediaContent(String url, String contentType) {}

public record DataPart(Map<String, Object> data, Map<String, Object> metadata) implements Part {}
```

### DataArgument

Runtime data for rendering a template.

```java
public class DataArgument {
    public static Builder builder();

    public Map<String, Object> getInput();
    public List<Document> getDocs();
    public List<Message> getMessages();
    public Map<String, Object> getContext();

    public static class Builder {
        public Builder input(Map<String, Object> input);
        public Builder docs(List<Document> docs);
        public Builder messages(List<Message> messages);
        public Builder context(Map<String, Object> context);
        public DataArgument build();
    }
}
```

### ToolDefinition

```java
public class ToolDefinition {
    public String getName();
    public String getDescription();
    public Object getInputSchema();
    public Object getOutputSchema();

    public static Builder builder();
}
```

## Stores

### DirStore

Load prompts from a filesystem directory (async).

```java
import com.google.dotprompt.store.DirStore;
import com.google.dotprompt.store.DirStoreOptions;

DirStore store = new DirStore(DirStoreOptions.builder()
    .directory("./prompts")
    .build());

CompletableFuture<PromptData> future = store.load("greeting", null);
PromptData prompt = future.join();
```

### DirStoreSync

Synchronous version.

```java
import com.google.dotprompt.store.DirStoreSync;
import com.google.dotprompt.store.DirStoreOptions;

DirStoreSync store = new DirStoreSync(DirStoreOptions.builder()
    .directory("./prompts")
    .build());

PromptData prompt = store.load("greeting", null);
```

## Resolvers

### ToolResolver

```java
@FunctionalInterface
public interface ToolResolver {
    CompletableFuture<ToolDefinition> resolve(String name);
}

// Usage
DotpromptOptions options = DotpromptOptions.builder()
    .toolResolver(name -> CompletableFuture.supplyAsync(() -> {
        // Look up tool definition
        return loadToolFromDatabase(name);
    }))
    .build();
```

